import React, { useState, useRef, useEffect } from 'react';
import { 
  Heart, Coffee, Code, Rocket, 
  Shield, Globe, MessageSquare, Star, MessageCircle, Send,
  Twitter, Github, Linkedin, Figma, X,
  Mail, Phone, MapPin, ExternalLink,
  Smile, Paperclip, Mic, Clock, Check, CheckCheck,
  User
} from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';

const Footer = ({ currentUser, isAuthenticated, onLogout }) => {
  const navigate = useNavigate();
  const currentYear = new Date().getFullYear();
  const [openChat, setOpenChat] = useState(false);
  const [messages, setMessages] = useState([]);
  const [inputMessage, setInputMessage] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [conversationId, setConversationId] = useState(null);
  const [conversation, setConversation] = useState(null);
  const messagesEndRef = useRef(null);
  const chatInputRef = useRef(null);

  // Vérifier si l'utilisateur est connecté avant d'ouvrir le chat
  const handleOpenChat = () => {
    if (!isAuthenticated || !currentUser) {
      navigate('/login');
      return;
    }
    setOpenChat(true);
  };

  // Charger la conversation et les messages
  useEffect(() => {
    if (openChat && isAuthenticated && currentUser) {
      loadOrCreateConversation();
    }
  }, [openChat, isAuthenticated, currentUser]);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  // Obtenir le token d'authentification
  const getAuthToken = () => {
    return localStorage.getItem('authToken') || sessionStorage.getItem('authToken');
  };

  // Charger ou créer une conversation
  const loadOrCreateConversation = async () => {
    if (!isAuthenticated || !currentUser) return;

    try {
      setIsLoading(true);
      const token = getAuthToken();

      // Utiliser la route getOrCreateConversation
      const response = await axios.post('/api/conversations/create', {}, {
        headers: { 
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json'
        }
      });

      if (response.data.success && response.data.conversation) {
        const conv = response.data.conversation;
        setConversationId(conv.id);
        setConversation(conv);
        loadMessages(conv.id);

        // Marquer la conversation comme lue
        if (currentUser.role === 'user') {
          await markConversationAsRead(conv.id);
        }
      }
    } catch (error) {
      console.error('Erreur chargement conversation:', error);
      // Message d'erreur
      setMessages([
        { 
          id: 1, 
          text: 'Erreur de chargement. Veuillez réessayer.', 
          time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }), 
          sender: 'bot', 
          status: 'read',
          sender_id: null
        }
      ]);
    } finally {
      setIsLoading(false);
    }
  };

  // Charger les messages d'une conversation
  const loadMessages = async (convId) => {
    try {
      const token = getAuthToken();
      const response = await axios.get(`/api/conversations/${convId}/messages`, {
        headers: { 'Authorization': `Bearer ${token}` }
      });

      if (response.data.success && response.data.messages) {
        const formattedMessages = response.data.messages.map(msg => ({
          id: msg.id,
          text: msg.content,
          time: new Date(msg.created_at).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
          sender: msg.sender_id === currentUser.id ? 'user' : 'admin',
          sender_id: msg.sender_id,
          is_read: msg.is_read,
          status: msg.is_read ? 'read' : 'sent',
          message_type: msg.message_type
        }));
        setMessages(formattedMessages);
      }
    } catch (error) {
      console.error('Erreur chargement messages:', error);
      // Message par défaut
      setMessages([
        { 
          id: 1, 
          text: 'Bonjour 👋 Bienvenue dans le support NexusAdmin.', 
          time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }), 
          sender: 'admin', 
          status: 'read',
          sender_id: null
        }
      ]);
    }
  };

  // Marquer une conversation comme lue
  const markConversationAsRead = async (convId) => {
    try {
      const token = getAuthToken();
      await axios.put(`/api/conversations/${convId}/read`, {}, {
        headers: { 'Authorization': `Bearer ${token}` }
      });
    } catch (error) {
      console.error('Erreur marquage comme lu:', error);
    }
  };

  // Marquer un message comme lu
  const markMessageAsRead = async (messageId) => {
    try {
      const token = getAuthToken();
      await axios.put(`/api/messages/${messageId}/read`, {}, {
        headers: { 'Authorization': `Bearer ${token}` }
      });
    } catch (error) {
      console.error('Erreur marquage message lu:', error);
    }
  };

  // Envoyer un message
  const handleSendMessage = async () => {
    if (!inputMessage.trim() || !isAuthenticated || !currentUser) return;

    // Message local immédiat
    const tempId = Date.now();
    const newMessage = {
      id: tempId,
      text: inputMessage,
      time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
      sender: 'user',
      status: 'sent',
      sender_id: currentUser.id,
      message_type: 'text'
    };

    setMessages(prev => [...prev, newMessage]);
    setInputMessage('');
    setIsTyping(true);

    try {
      const token = getAuthToken();

      // Utiliser la route sendMessage
      const response = await axios.post('/api/messages', {
        content: inputMessage,
        conversation_id: conversationId
      }, {
        headers: { 'Authorization': `Bearer ${token}` }
      });

      if (response.data.success && response.data.message) {
        const savedMessage = response.data.message;

        // Remplacer le message temporaire par le message réel
        setMessages(prev => prev.map(msg => 
          msg.id === tempId 
            ? {
                ...msg,
                id: savedMessage.id,
                time: new Date(savedMessage.created_at).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
                status: 'delivered'
              }
            : msg
        ));
      }

      // Pour les utilisateurs, simuler une réponse automatique
      if (currentUser.role === 'user') {
        setTimeout(() => {
          const responses = [
            "Merci pour votre message. Notre équipe vous répondra rapidement.",
            "Message reçu ! Nous traitons votre demande.",
            "Nous avons bien noté votre question. Un conseiller vous contactera bientôt.",
            "Votre message a été transféré à notre équipe de support."
          ];

          const randomResponse = responses[Math.floor(Math.random() * responses.length)];

          const botMessage = {
            id: Date.now(),
            text: randomResponse,
            time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
            sender: 'admin',
            status: 'read',
            sender_id: null,
            message_type: 'text'
          };

          setMessages(prev => [...prev, botMessage]);
          setIsTyping(false);
        }, 2000);
      } else {
        setIsTyping(false);
      }

    } catch (error) {
      console.error('Erreur envoi message:', error);
      setIsTyping(false);

      // Message d'erreur
      setMessages(prev => [...prev, {
        id: Date.now(),
        text: '⚠️ Erreur d\'envoi. Veuillez réessayer.',
        time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
        sender: 'system',
        status: 'read',
        sender_id: null
      }]);
    }
  };

  const handleKeyPress = (e) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSendMessage();
    }
  };

  useEffect(() => {
    if (openChat) {
      setTimeout(() => {
        chatInputRef.current?.focus();
      }, 300);
    }
  }, [openChat]);

  // Fermer le chat
  const handleCloseChat = () => {
    setOpenChat(false);
    setMessages([]);
    setInputMessage('');
    setIsTyping(false);
    setConversationId(null);
    setConversation(null);
  };

  // Rediriger vers la page messages complète
  const handleGoToFullMessages = () => {
    handleCloseChat();
    navigate('/messages');
  };

  // Obtenir le nom de l'interlocuteur
  const getInterlocutorName = () => {
    if (!conversation) return 'Support';

    if (currentUser.role === 'user' && conversation.admin) {
      return `${conversation.admin.first_name} ${conversation.admin.last_name}`;
    } else if (currentUser.role === 'admin' && conversation.user) {
      return `${conversation.user.first_name} ${conversation.user.last_name}`;
    }
    return 'Support';
  };

  // Obtenir le statut du chat
  const getChatStatus = () => {
    if (!isAuthenticated || !currentUser) return 'Hors ligne';
    if (currentUser.role === 'admin') return 'En ligne • Support';
    return 'En ligne • Réponse rapide';
  };

  return (
    <footer className="relative">
      {/* Main Footer */}
      <div className="bg-gradient-to-br from-white to-white/80 dark:from-neutral-900 dark:to-neutral-900/80 backdrop-blur-xl border-t border-white/40 dark:border-neutral-800/60">
        {/* Top Section */}
        <div className="max-w-7xl mx-auto px-6 lg:px-8 py-12">
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-8 lg:gap-12">

            {/* Brand Column */}
            <div className="lg:col-span-1">
              <div className="flex items-center space-x-3 mb-6">
                <div className="h-10 w-10 rounded-xl bg-gradient-to-r from-primary-500 to-secondary-500 flex items-center justify-center shadow-lg">
                  <Rocket className="h-6 w-6 text-white" />
                </div>
                <div>
                  <h2 className="text-2xl font-bold bg-gradient-to-r from-primary-600 to-secondary-600 bg-clip-text text-transparent">
                    NexusAdmin
                  </h2>
                  <p className="text-sm text-neutral-600 dark:text-neutral-400">Dashboard Premium</p>
                </div>
              </div>
              <p className="text-neutral-700 dark:text-neutral-300 mb-6">
                Une plateforme d'administration moderne et intuitive pour gérer vos projets efficacement.
              </p>
              <div className="flex items-center space-x-4">
                <SocialLink href="#" icon={<Twitter className="h-5 w-5" />} label="Twitter" />
                <SocialLink href="#" icon={<Github className="h-5 w-5" />} label="GitHub" />
                <SocialLink href="#" icon={<Linkedin className="h-5 w-5" />} label="LinkedIn" />
                <SocialLink href="#" icon={<Figma className="h-5 w-5" />} label="Figma" />
              </div>
            </div>

            {/* Links Column */}
            <div>
              <h3 className="text-lg font-bold text-neutral-900 dark:text-white mb-6">Navigation</h3>
              <ul className="space-y-3">
                <FooterLink href="/" label="Accueil" />
                <FooterLink href="/services" label="Services" />
                <FooterLink href="/portfolio" label="Portfolio" />
                <FooterLink href="/contact" label="Contact" />
                <FooterLink href="/messages" label="Messages" />
                {currentUser?.role === 'admin' && (
                  <FooterLink href="/admin" label="Tableau de bord" />
                )}
              </ul>
            </div>

            {/* Resources Column */}
            <div>
              <h3 className="text-lg font-bold text-neutral-900 dark:text-white mb-6">Ressources</h3>
              <ul className="space-y-3">
                <FooterLink href="/api-docs" label="Documentation API" icon={<Code className="h-4 w-4" />} />
                <FooterLink href="/changelog" label="Changelog" icon={<Rocket className="h-4 w-4" />} />
                <FooterLink href="/security" label="Sécurité" icon={<Shield className="h-4 w-4" />} />
                <FooterLink href="/status" label="Statut" icon={<Globe className="h-4 w-4" />} />
                <FooterLink href="/support" label="Support" icon={<MessageSquare className="h-4 w-4" />} />
                <FooterLink href="/contribute" label="Contribuer" icon={<Star className="h-4 w-4" />} />
              </ul>
            </div>

            {/* Contact Column */}
            <div>
              <h3 className="text-lg font-bold text-neutral-900 dark:text-white mb-6">Contact</h3>
              <ul className="space-y-4">
                <li className="flex items-center space-x-3">
                  <div className="h-10 w-10 rounded-lg bg-primary-500/10 flex items-center justify-center">
                    <Mail className="h-5 w-5 text-primary-500" />
                  </div>
                  <div>
                    <p className="font-medium text-neutral-900 dark:text-white">Email</p>
                    <p className="text-sm text-neutral-600 dark:text-neutral-400">support@nexusadmin.com</p>
                  </div>
                </li>
                <li className="flex items-center space-x-3">
                  <div className="h-10 w-10 rounded-lg bg-secondary-500/10 flex items-center justify-center">
                    <Phone className="h-5 w-5 text-secondary-500" />
                  </div>
                  <div>
                    <p className="font-medium text-neutral-900 dark:text-white">Téléphone</p>
                    <p className="text-sm text-neutral-600 dark:text-neutral-400">+33 1 23 45 67 89</p>
                  </div>
                </li>
                <li className="flex items-center space-x-3">
                  <div className="h-10 w-10 rounded-lg bg-emerald-500/10 flex items-center justify-center">
                    <MapPin className="h-5 w-5 text-emerald-500" />
                  </div>
                  <div>
                    <p className="font-medium text-neutral-900 dark:text-white">Adresse</p>
                    <p className="text-sm text-neutral-600 dark:text-neutral-400">Paris, France</p>
                  </div>
                </li>
              </ul>
            </div>
          </div>

          {/* Newsletter */}
          <div className="mt-12 pt-8 border-t border-neutral-200 dark:border-neutral-800">
            <div className="max-w-2xl mx-auto text-center">
              <h3 className="text-xl font-bold text-neutral-900 dark:text-white mb-3">
                Restez informé
              </h3>
              <p className="text-neutral-600 dark:text-neutral-400 mb-6">
                Recevez les dernières mises à jour et nouveautés directement dans votre boîte mail.
              </p>
              <div className="flex flex-col sm:flex-row gap-3 max-w-md mx-auto">
                <input
                  type="email"
                  placeholder="Votre adresse email"
                  className="flex-1 px-4 py-3 rounded-xl border border-neutral-300 dark:border-neutral-700 bg-white dark:bg-neutral-800 text-neutral-900 dark:text-white placeholder-neutral-500 focus:outline-none focus:ring-2 focus:ring-primary-500/20 focus:border-primary-500"
                />
                <button className="px-6 py-3 rounded-xl bg-gradient-to-r from-primary-500 to-secondary-500 text-white font-medium hover:shadow-lg hover:shadow-primary-500/25 transition-all duration-300">
                  S'abonner
                </button>
              </div>
            </div>
          </div>
        </div>

        {/* Bottom Section */}
        <div className="border-t border-neutral-200 dark:border-neutral-800">
          <div className="max-w-7xl mx-auto px-6 lg:px-8 py-6">
            <div className="flex flex-col md:flex-row items-center justify-between gap-4">

              {/* Copyright */}
              <div className="flex items-center space-x-2 text-sm text-neutral-600 dark:text-neutral-400">
                <span>© {currentYear} NexusAdmin. Tous droits réservés.</span>
                <span className="hidden sm:inline">•</span>
                <div className="flex items-center space-x-2">
                  <span>Fait avec</span>
                  <Heart className="h-4 w-4 text-red-500 fill-red-500" />
                  <span>et</span>
                  <Coffee className="h-4 w-4 text-amber-600" />
                  <span>par</span>
                  <span className="font-medium text-primary-600 dark:text-primary-400">L'équipe Nexus</span>
                </div>
              </div>

              {/* Legal */}
              <div className="flex items-center space-x-6 text-sm">
                <a href="/privacy" className="text-neutral-600 dark:text-neutral-400 hover:text-primary-600 dark:hover:text-primary-400 transition-colors">
                  Politique de confidentialité
                </a>
                <a href="/terms" className="text-neutral-600 dark:text-neutral-400 hover:text-primary-600 dark:hover:text-primary-400 transition-colors">
                  Conditions d'utilisation
                </a>
                <a href="/cookies" className="text-neutral-600 dark:text-neutral-400 hover:text-primary-600 dark:hover:text-primary-400 transition-colors">
                  Cookies
                </a>
                <a href="/legal" className="flex items-center space-x-1 text-primary-600 dark:text-primary-400 hover:text-primary-700 dark:hover:text-primary-300 transition-colors">
                  <span>Mentions légales</span>
                  <ExternalLink className="h-3 w-3" />
                </a>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Bouton Chat flottant */}
      <button
        onClick={handleOpenChat}
        className={`fixed bottom-6 right-6 h-14 w-14 rounded-full bg-gradient-to-r from-primary-500 to-secondary-500 text-white shadow-2xl shadow-primary-500/30 flex items-center justify-center hover:scale-110 active:scale-95 transition-all duration-300 z-40 group ${openChat ? 'opacity-0 pointer-events-none' : 'opacity-100'}`}
        aria-label="Ouvrir le chat de support"
      >
        <MessageCircle className="h-6 w-6" />
        <span className="absolute -top-2 -right-2 h-5 w-5 bg-red-500 rounded-full border-2 border-white dark:border-neutral-900 animate-pulse"></span>
        <span className="absolute -top-12 right-0 px-2 py-1 bg-neutral-800 text-white text-xs rounded-lg opacity-0 group-hover:opacity-100 transition-opacity whitespace-nowrap">
          {isAuthenticated && currentUser ? `Chat avec ${currentUser.role === 'user' ? 'Support' : 'Clients'}` : 'Se connecter pour chatter'}
        </span>
      </button>

      {/* Chat Modal */}
      {openChat && (
        <div className="fixed bottom-6 right-6 w-80 sm:w-96 bg-gradient-to-br from-white to-white/90 dark:from-neutral-900 dark:to-neutral-900/90 backdrop-blur-xl rounded-2xl shadow-2xl border border-white/40 dark:border-neutral-800/60 z-50 overflow-hidden animate-fadeInUp">

          {/* Header */}
          <div className="p-4 bg-gradient-to-r from-primary-500 to-secondary-500 text-white flex items-center justify-between">
            <div className="flex items-center space-x-3">
              <div className="h-8 w-8 rounded-full bg-white/20 flex items-center justify-center">
                {currentUser?.role === 'admin' ? <User className="h-4 w-4" /> : <MessageCircle className="h-4 w-4" />}
              </div>
              <div>
                <span className="font-bold text-sm">
                  {currentUser?.role === 'admin' ? 'Messages Clients' : 'Support Nexus'}
                </span>
                <p className="text-xs opacity-80">
                  {getChatStatus()}
                </p>
              </div>
            </div>
            <div className="flex items-center space-x-2">
              {currentUser?.role === 'admin' && (
                <button 
                  onClick={handleGoToFullMessages}
                  className="text-xs bg-white/20 hover:bg-white/30 px-2 py-1 rounded transition-colors"
                  title="Ouvrir la messagerie complète"
                >
                  Voir tout
                </button>
              )}
              <button 
                onClick={handleCloseChat}
                className="h-8 w-8 rounded-full bg-white/20 hover:bg-white/30 flex items-center justify-center transition-colors"
                aria-label="Fermer le chat"
              >
                <X className="h-4 w-4" />
              </button>
            </div>
          </div>

          {/* Messages Area */}
          <div className="h-64 sm:h-72 p-4 overflow-y-auto scrollbar-thin scrollbar-thumb-neutral-300 dark:scrollbar-thumb-neutral-700">
            {!isAuthenticated || !currentUser ? (
              <div className="flex flex-col items-center justify-center h-full text-center">
                <MessageCircle className="h-16 w-16 text-neutral-400 mb-4" />
                <h3 className="font-bold text-neutral-900 dark:text-white mb-2">
                  Connectez-vous pour discuter
                </h3>
                <p className="text-neutral-600 dark:text-neutral-400 mb-6 max-w-xs">
                  Pour utiliser le chat de support, vous devez être connecté à votre compte.
                </p>
                <div className="flex flex-col sm:flex-row gap-3">
                  <button
                    onClick={() => navigate('/login')}
                    className="px-4 py-2 bg-gradient-to-r from-primary-500 to-secondary-500 text-white rounded-xl hover:shadow-lg transition-all"
                  >
                    Se connecter
                  </button>
                  <button
                    onClick={() => navigate('/register')}
                    className="px-4 py-2 bg-neutral-200 dark:bg-neutral-800 text-neutral-700 dark:text-neutral-300 rounded-xl hover:bg-neutral-300 dark:hover:bg-neutral-700 transition-colors"
                  >
                    S'inscrire
                  </button>
                </div>
              </div>
            ) : isLoading ? (
              <div className="flex items-center justify-center h-full">
                <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary-500"></div>
              </div>
            ) : (
              <div className="space-y-3">
                {messages.length === 0 ? (
                  <div className="text-center py-8">
                    <MessageCircle className="h-12 w-12 text-neutral-400 mx-auto mb-4" />
                    <p className="text-neutral-600 dark:text-neutral-400">
                      {currentUser.role === 'user' 
                        ? 'Démarrez la conversation avec notre support'
                        : 'Aucun message dans cette conversation'}
                    </p>
                  </div>
                ) : (
                  messages.map((msg) => (
                    <div
                      key={msg.id}
                      className={`flex ${msg.sender === 'user' || (msg.sender === 'admin' && msg.sender_id !== currentUser.id) ? 'justify-start' : 'justify-end'}`}
                    >
                      <div className={`max-w-[85%] rounded-2xl p-3 ${
                        msg.sender === 'user' || (msg.sender === 'admin' && msg.sender_id !== currentUser.id)
                        ? 'bg-neutral-100 dark:bg-neutral-800 text-neutral-900 dark:text-white rounded-bl-none'
                        : 'bg-gradient-to-r from-primary-500 to-secondary-500 text-white rounded-br-none'
                      }`}>
                        <p className="text-sm">{msg.text}</p>
                        <div className={`flex items-center justify-between mt-2 ${
                          msg.sender === 'user' || (msg.sender === 'admin' && msg.sender_id !== currentUser.id) 
                          ? 'text-neutral-500' 
                          : 'text-white/80'
                        }`}>
                          <span className="text-xs">{msg.time}</span>
                          {(msg.sender === 'user' && msg.sender_id === currentUser.id) && (
                            <div className="flex items-center space-x-1">
                              {msg.status === 'sent' && <Check className="h-3 w-3" />}
                              {msg.status === 'delivered' && <CheckCheck className="h-3 w-3" />}
                              {msg.status === 'read' && <CheckCheck className="h-3 w-3 text-blue-400" />}
                            </div>
                          )}
                        </div>
                      </div>
                    </div>
                  ))
                )}

                {isTyping && (
                  <div className="flex justify-start">
                    <div className="bg-neutral-100 dark:bg-neutral-800 rounded-2xl rounded-bl-none p-3">
                      <div className="flex items-center space-x-2">
                        <div className="flex space-x-1">
                          <div className="h-2 w-2 bg-neutral-400 rounded-full animate-bounce" style={{ animationDelay: '0ms' }}></div>
                          <div className="h-2 w-2 bg-neutral-400 rounded-full animate-bounce" style={{ animationDelay: '150ms' }}></div>
                          <div className="h-2 w-2 bg-neutral-400 rounded-full animate-bounce" style={{ animationDelay: '300ms' }}></div>
                        </div>
                        <span className="text-xs text-neutral-500">
                          {currentUser.role === 'user' ? 'Support écrit...' : 'En train d\'écrire...'}
                        </span>
                      </div>
                    </div>
                  </div>
                )}

                <div ref={messagesEndRef} />
              </div>
            )}
          </div>

          {/* Input Area */}
          <div className="p-3 border-t border-neutral-200 dark:border-neutral-800 bg-white/50 dark:bg-neutral-900/50">
            {!isAuthenticated || !currentUser ? (
              <div className="text-center py-4">
                <p className="text-sm text-neutral-600 dark:text-neutral-400">
                  Connectez-vous pour envoyer des messages
                </p>
              </div>
            ) : (
              <div className="flex items-center space-x-2">
                <button className="p-2 rounded-lg hover:bg-neutral-100 dark:hover:bg-neutral-800 transition-colors">
                  <Paperclip className="h-5 w-5 text-neutral-600 dark:text-neutral-400" />
                </button>
                <div className="flex-1 relative">
                  <input
                    ref={chatInputRef}
                    type="text"
                    value={inputMessage}
                    onChange={(e) => setInputMessage(e.target.value)}
                    onKeyPress={handleKeyPress}
                    placeholder={
                      currentUser.role === 'user' 
                        ? "Écrivez votre message au support..."
                        : "Répondre au client..."
                    }
                    disabled={isTyping || isLoading}
                    className="w-full pl-3 pr-10 py-2.5 rounded-xl border border-neutral-300 dark:border-neutral-700 bg-white dark:bg-neutral-800 text-neutral-900 dark:text-white placeholder-neutral-500 focus:outline-none focus:ring-2 focus:ring-primary-500/20 focus:border-primary-500 disabled:opacity-50 disabled:cursor-not-allowed"
                  />
                  <button className="absolute right-3 top-1/2 transform -translate-y-1/2 p-1">
                    <Mic className="h-4 w-4 text-neutral-600 dark:text-neutral-400" />
                  </button>
                </div>
                <button
                  onClick={handleSendMessage}
                  disabled={!inputMessage.trim() || isTyping || isLoading}
                  className={`p-2.5 rounded-xl transition-all duration-300 ${inputMessage.trim() && !isTyping && !isLoading
                    ? 'bg-gradient-to-r from-primary-500 to-secondary-500 text-white hover:shadow-lg hover:shadow-primary-500/25'
                    : 'bg-neutral-200 dark:bg-neutral-700 text-neutral-400 cursor-not-allowed'
                  }`}
                >
                  <Send className="h-5 w-5" />
                </button>
              </div>
            )}
          </div>

          {/* Chat Info */}
          <div className="px-4 py-2 border-t border-neutral-200 dark:border-neutral-800 bg-neutral-50 dark:bg-neutral-800/50">
            <div className="flex items-center justify-between">
              <div className="flex items-center space-x-2">
                <Clock className="h-3 w-3 text-neutral-500" />
                <span className="text-xs text-neutral-600 dark:text-neutral-400">
                  {currentUser.role === 'user' 
                    ? 'Réponse: <strong>2-5 min</strong>'
                    : `Discussion avec: <strong>${getInterlocutorName()}</strong>`
                  }
                </span>
              </div>
              <div className="flex items-center space-x-1">
                <div className="h-2 w-2 rounded-full bg-green-500 animate-pulse"></div>
                <span className="text-xs text-neutral-600 dark:text-neutral-400">
                  {isAuthenticated && currentUser ? 'En ligne' : 'Hors ligne'}
                </span>
              </div>
            </div>
          </div>
        </div>
      )}
    </footer>
  );
};

// Composants réutilisables
const SocialLink = ({ href, icon, label }) => (
  <a
    href={href}
    aria-label={label}
    className="h-10 w-10 rounded-xl bg-neutral-100 dark:bg-neutral-800 flex items-center justify-center text-neutral-600 dark:text-neutral-400 hover:bg-primary-500/10 hover:text-primary-600 dark:hover:text-primary-400 transition-all duration-300 hover:scale-110"
    target="_blank"
    rel="noopener noreferrer"
  >
    {icon}
  </a>
);

const FooterLink = ({ href, label, icon }) => (
  <li>
    <a
      href={href}
      className="flex items-center space-x-2 text-neutral-600 dark:text-neutral-400 hover:text-primary-600 dark:hover:text-primary-400 transition-colors group"
    >
      {icon && <span className="opacity-60 group-hover:opacity-100">{icon}</span>}
      <span>{label}</span>
    </a>
  </li>
);

export default Footer;
